local PaintbrushMaker = {}
local PRODUCTS = {
    iron_paintbrush = { name = "Železni čopič", ironCost = 1, woodCost = 3, leatherCost = 2, time = 4, cost = 130, prestige = 3, happiness = 2, description = "Železni čopič za osnovne slikarje." },
    bronze_paintbrush = { name = "Bronast čopič", bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 2, time = 6, cost = 320, prestige = 5, happiness = 3, description = "Bronast čopič za atelje." },
    silver_paintbrush = { name = "Srebrni čopič", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 2, time = 10, cost = 780, prestige = 10, happiness = 4, description = "Srebrni čopič za plemiške slikarje." },
    gilded_paintbrush = { name = "Pozlačeni čopič", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 2, time = 14, cost = 1700, prestige = 19, happiness = 5, description = "Pozlačeni čopič za dvorne slikarje." },
    jewel_set_paintbrush = { name = "Draguljasti čopič", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 2, time = 18, cost = 3700, prestige = 35, happiness = 7, description = "Draguljasti čopič za kraljeve slikarje." },
    royal_sovereign_paintbrush = { name = "Kraljevski suvereni čopič", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 2, time = 25, cost = 8000, prestige = 67, happiness = 13, description = "Suvereni čopič z biseri za krono." },
}
local BUILDINGS = {
    paintbrush_workshop = { name = "Čopična delavnica", cost = { gold = 300, wood = 180, stone = 125, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    paintbrush_house = { name = "Čopična hiša", cost = { gold = 1110, wood = 360, stone = 255, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_paintbrush_atelier = { name = "Mojstrski čopični atelje", cost = { gold = 2850, wood = 420, stone = 495, silver = 32, gold = 6 }, upkeep = 67, qualityBonus = 30 },
    sovereign_paintbrush_palace = { name = "Suverena čopična palača", cost = { gold = 12400, wood = 640, stone = 800, gold = 79, jewel = 18 }, upkeep = 245, qualityBonus = 55, prestigeBonus = 50 },
}
PaintbrushMaker.ironStock = 10; PaintbrushMaker.bronzeStock = 8; PaintbrushMaker.woodStock = 16; PaintbrushMaker.leatherStock = 12; PaintbrushMaker.silverStock = 8; PaintbrushMaker.goldStock = 6; PaintbrushMaker.jewelStock = 4; PaintbrushMaker.pearlStock = 4
PaintbrushMaker.productStock = {}; PaintbrushMaker.buildings = {}; PaintbrushMaker.maker = nil; PaintbrushMaker.activeMaking = {}; PaintbrushMaker.totalProducts = 0; PaintbrushMaker.dayTimer = 0
function PaintbrushMaker.init() PaintbrushMaker.ironStock=10; PaintbrushMaker.bronzeStock=8; PaintbrushMaker.woodStock=16; PaintbrushMaker.leatherStock=12; PaintbrushMaker.silverStock=8; PaintbrushMaker.goldStock=6; PaintbrushMaker.jewelStock=4; PaintbrushMaker.pearlStock=4; PaintbrushMaker.productStock={}; PaintbrushMaker.buildings={}; PaintbrushMaker.maker=nil; PaintbrushMaker.activeMaking={}; PaintbrushMaker.totalProducts=0; PaintbrushMaker.dayTimer=0; print("[PaintbrushMaker] Royal Paintbrush Maker System initialized (6 products, 4 buildings)") end
function PaintbrushMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PaintbrushMaker.maker={name=n or ("Čopičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čopičar najet: %s (spretnost: %d)",PaintbrushMaker.maker.name,s),"success") end; return true end
function PaintbrushMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PaintbrushMaker.build(id) local ok,e=PaintbrushMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PaintbrushMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PaintbrushMaker.getQualityBonus() local b=0; for _,bd in ipairs(PaintbrushMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PaintbrushMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PaintbrushMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PaintbrushMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PaintbrushMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PaintbrushMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PaintbrushMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PaintbrushMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PaintbrushMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PaintbrushMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PaintbrushMaker.buildings==0 then return false,"Potrebna čopična delavnica" end; if not PaintbrushMaker.maker then return false,"Potreben čopičar" end; return true end
function PaintbrushMaker.make(pt,qty) qty=qty or 1; local ok,e=PaintbrushMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PaintbrushMaker.ironStock=PaintbrushMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PaintbrushMaker.bronzeStock=PaintbrushMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PaintbrushMaker.woodStock=PaintbrushMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PaintbrushMaker.leatherStock=PaintbrushMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PaintbrushMaker.silverStock=PaintbrushMaker.silverStock-d.silverCost*qty end; if d.goldCost then PaintbrushMaker.goldStock=PaintbrushMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PaintbrushMaker.jewelStock=PaintbrushMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PaintbrushMaker.pearlStock=PaintbrushMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PaintbrushMaker.maker then t=math.max(1,t-math.floor(PaintbrushMaker.maker.skill/13)) end; table.insert(PaintbrushMaker.activeMaking,{id="paintbrush_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PaintbrushMaker.completeMaking(m) local q=1.0+(PaintbrushMaker.getQualityBonus()/100); if PaintbrushMaker.maker then q=q+(PaintbrushMaker.maker.skill/140) end; q=math.min(2.5,q); PaintbrushMaker.productStock[m.productType]=(PaintbrushMaker.productStock[m.productType] or 0)+m.quantity; PaintbrushMaker.totalProducts=PaintbrushMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PaintbrushMaker.maker then PaintbrushMaker.maker.itemsMade=PaintbrushMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PaintbrushMaker.maker.skill=math.min(100,PaintbrushMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čopič izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"paintbrush.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PaintbrushMaker.update(dt) if not _G.state then return end; PaintbrushMaker.dayTimer=PaintbrushMaker.dayTimer+dt; if PaintbrushMaker.dayTimer>=30 then PaintbrushMaker.dayTimer=0; for i=#PaintbrushMaker.activeMaking,1,-1 do local m=PaintbrushMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PaintbrushMaker.completeMaking(m); table.remove(PaintbrushMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PaintbrushMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PaintbrushMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PaintbrushMaker.getStats() return {ironStock=PaintbrushMaker.ironStock,bronzeStock=PaintbrushMaker.bronzeStock,woodStock=PaintbrushMaker.woodStock,leatherStock=PaintbrushMaker.leatherStock,silverStock=PaintbrushMaker.silverStock,goldStock=PaintbrushMaker.goldStock,jewelStock=PaintbrushMaker.jewelStock,pearlStock=PaintbrushMaker.pearlStock,productStock=PaintbrushMaker.productStock,numBuildings=#PaintbrushMaker.buildings,hasMaker=PaintbrushMaker.maker~=nil,makerName=PaintbrushMaker.maker and PaintbrushMaker.maker.name or "—",makerSkill=PaintbrushMaker.maker and PaintbrushMaker.maker.skill or 0,activeMaking=#PaintbrushMaker.activeMaking,totalProducts=PaintbrushMaker.totalProducts} end
return PaintbrushMaker
